import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";
import LogsWidget from "../components/LogsWidget";
import "./AdminDashboard.css"; // Import CSS file

const AdminDashboard = () => {
  const [darkMode, setDarkMode] = useState(false);
  const navigate = useNavigate(); // Hook for navigation

  const errorRate = "2.5%"; // Example error rate

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleAutomateResolution = () => {
    alert("Automated resolution triggered!");
    // Add API call or logic for triggering automation
  };

  // Logout handler
  const handleLogout = () => {
    localStorage.removeItem("token"); // Remove token from localStorage
    navigate("/login"); // Redirect to login page
  };

  return (
    <div className={`admin-dashboard ${darkMode ? "dark-mode" : "light-mode"}`}>
      {/* Navbar */}
      <div className="navbar">
        <h1 style={{
    margin: "0 auto",
    fontSize: "2.5rem",
    textAlign: "center",
    color: "#4caf50",
    fontWeight: "bold",
  }} >Admin Dashboard</h1>
        <div className="button-group">
          <button onClick={handleToggleDarkMode}>
            Toggle {darkMode ? "Light" : "Dark"} Mode
          </button>
          <button className="logout-btn" onClick={handleLogout}>Logout</button>
        </div>
      </div>

      {/* Widgets Section */}
      <div className="widgets-container">
        <MonitoringWidget />
        <LogsWidget />
        <MLWidget />

        {/* Error Rates Widget */}
        <div className="widget error-widget">
          <h3>Error Rates</h3>
          <p className="error-rate">{errorRate}</p>
        </div>

        {/* Automated Resolution Widget */}
        <div className="widget automation-widget">
          <h3>Automated Resolution</h3>
          <button onClick={handleAutomateResolution}>Trigger Automation</button>
          <p className="automation-text">
            This will automatically resolve common server issues, including:
          </p>
          <ul className="automation-list">
            <li>Clearing cache</li>
            <li>Restarting affected services</li>
            <li>Freeing up memory</li>
            <li>Updating configuration files</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
